class Solution {
    public String robotWithString(String s){
        int[] frequency=new int[26];
        for(char ch:s.toCharArray())frequency[ch-'a']++;
        int smallest=0;
        StringBuilder stack=new StringBuilder(),answer=new StringBuilder();
        for(char ch:s.toCharArray()){
            stack.append(ch);
            frequency[ch-'a']--;
            while(smallest<26&&frequency[smallest]==0)smallest++;
            while(stack.length()>0&&(smallest==26||stack.charAt(stack.length()-1)-'a'<=smallest)){
                answer.append(stack.charAt(stack.length()-1));
                stack.setLength(stack.length()-1);
            }
        }
        return answer.toString();
    }
}

